def upgrade() -> None:
    # Keep the historical tables and all their rows intact. Existing API mappings
    # continue to use these tables through the solarverse_legacy schema.
    op.execute("SET LOCAL search_path TO public")
    op.execute("CREATE SCHEMA solarverse_legacy")
    for table_name in LEGACY_TABLES:
        op.execute(f'ALTER TABLE public."{table_name}" SET SCHEMA solarverse_legacy')
    for statement in CANONICAL_DDL:
        op.execute(statement)


def downgrade() -> None:
    raise RuntimeError(
        "Revision 006 is forward-only: canonical v1.2 records may exist. "
        "Restore from a verified backup using an approved recovery plan instead."
    )
